UPDATE companies SET description='Plantible Foods operates from Eldorado, Texas. The company was co-founded by Tony Martens and Maurits van de Ven, who began by living in trailers at a two-acre duckweed farm in San Diego during the California lockdown.

The company cultivates Lemna, a fast-growing aquatic plant also known as duckweed, on aqua farms and extracts Rubi Protein™, a complete protein containing all nine essential amino acids and vitamin B12. The process uses significantly less water and land than traditional protein sources, with the San Diego farm spanning two acres.

Plantible supplies Rubi Protein™ to food manufacturers for use in baked goods, plant-based meat and dairy alternatives, and sports and adult nutrition products. The ingredient is marketed as a functional replacement for eggs, butter, and chemical binders such as methylcellulose.

The founders started Plantible to address the challenge of sustainably feeding a growing global population. They emphasize a supply chain that requires 10 times less water than soybeans, uses zero arable land, and captures 10 times more CO2 than a forest, positioning Rubi Protein™ as a scalable, allergen-free protein solution.', certifications=ARRAY[]::text[], profile='{"capabilities": ["Lemna (duckweed) cultivation on aqua farms", "Rubi Protein\u2122 extraction and purification", "Plant-based protein ingredient manufacturing"], "industries": ["Food and beverage", "Plant-based meat", "Dairy alternatives", "Bakery", "Sports nutrition", "Adult nutrition"], "materials": ["Lemna (duckweed)", "Rubi Protein\u2122"], "equipment": [], "volume": "", "lead_time": "", "tolerances": "", "built_on": [], "facts_used": ["Headquarters: Eldorado, Texas -> db", "Founders: Tony Martens and Maurits van de Ven -> /", "Origin story: lived in trailers at two-acre duckweed farm in San Diego during California lockdown -> /", "Product: Rubi Protein\u2122 (complete protein, all nine essential amino acids, vitamin B12, neutral taste, allergen-free) -> /", "Process: Growing Lemna on aqua farms, extracting Rubi Protein\u2122 -> /", "Sustainability claims: 10x less water than soybeans, zero arable land, 10x more CO2 capture than forest -> /", "Applications: baked goods, plant-based meat, dairy alternatives, sports/adult nutrition -> /", "Company type: Manufacturer (produces Rubi Protein\u2122) -> /"], "company_type": "Manufacturer", "makes_products": "yes", "type_evidence": "We grow Lemna and extract Rubi Protein\u2122 in a sustainable and efficient way.", "founded_year": "", "employee_count": "", "cage_code": "", "min_order": "", "export_compliance": [], "languages": [], "social_links": [], "ownership_tags": []}'::jsonb, updated_at=now() WHERE slug='plantible-foods-eldorado' AND approved AND profile IS NULL;
UPDATE companies SET description='Plasman''s Lawrenceburg, Tennessee facility operates as part of a global automotive components manufacturer headquartered in Windsor, Canada, with European headquarters in Gothenburg, Sweden.

